def check_case(k):
    val = 5**k + 3
    if val <= 1:
        return None
    n = val.bit_length() - 1
    if 2**n == val:
        return n
    return None

results = {}
for k in range(1, 11):
    n = check_case(k)
    if n is not None:
        results[k] = n

print(results)

def check_power_of_5(N):
    if N < 1:
        return False
    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
    return True

print("Checking n=3 to n=20:")
solutions = []
for n in range(3, 21):
    target = (2**n) - 3
    if check_power_of_5(target):
        solutions.append(n)
        print(f"n={n}: 2^{n} - 3 = {target} (Power of 5)")
    # Optional: print status for all
